reports.query:
// CARD - "Pathao Pay drill-down" (report type: Graph)
//
// Parameter: $neodash_focus, set by clicking any node (property `click`).
// Unset  -> defaults to 'root', so the card opens on the Pathao Pay node.
//
// Reveal rule: show the focus node, its ancestors (the breadcrumb back
// to Pathao Pay) and its direct children. One click = one level deeper:
//
//   Pathao Pay -> Customers -> C1..Cn -> Customer-<acc> -> TXN_TYPE_D_C
//     -> Credit -> P2P / TOP UP / CASH OUT / ... -> Customer-<acc> + END
//     -> Debit  -> TXN_TYPE -> P2P / TOP UP / ...  -> Customer-<acc> + END
//
// The level-10 fan-out stops once the counterparty amounts balance the
// transaction type's total; the END node marks that point. Clicking END
// sets focus back to 'root' because its `click` property holds 'root' -
// which is the cycle.
//
// STALE FOCUS. NeoDash keeps `neodash_focus` in browser localStorage, so
// it survives a rebuild of the tree. Rebuilding renames keys, and a
// focus pointing at a key that no longer exists would match nothing and
// draw an EMPTY CARD with no error - which looks exactly like a broken
// dashboard. The OPTIONAL MATCH below falls back to 'root' in that case,
// so a stale parameter costs you the drill-down position and nothing else.
// PAGING AT LEVEL 2. All 38 customer pages hang off the root, but only
// page 1 is revealed automatically - otherwise Pathao Pay would fan out
// into 38 near-identical nodes. Pages 2+ are reached only by clicking
// the page node, whose `click` points at the next page, so the level
// behaves like one node cycling through tens rather than a fan-out.
WITH coalesce($neodash_focus, 'root') AS fk
OPTIONAL MATCH (stale:Nav {key: fk})
WITH CASE WHEN stale IS NULL THEN 'root' ELSE fk END AS fk
MATCH (f:Nav {key: fk})
MATCH (n:Nav)
WHERE f.path STARTS WITH n.path      // ancestors of the focus, and the focus itself
   OR (n.parent_key = f.key          // the focus node's direct children ...
       AND (NOT n:CustomerPage OR n.page = 1))   // ... but only page 1 of them
WITH collect(DISTINCT n) AS shown
UNWIND shown AS a
MATCH p = (a)-[:EXPANDS]->(b)
WHERE b IN shown
RETURN p

// CARD - "Transactions" (report type: Table)
// Every column of the source table, exactly as supplied.
//
// DYNAMIC: the table follows whichever node is selected in the graph.
// Each Nav node carries four filter properties written by
// cypher/03_build_nav_graph.cypher, and this card applies whichever of
// them are set:
//
//   f_acc   STATEMENT_FOR_ACC  - set from the C1..Cn level downwards
//   f_dc    TXN_TYPE_D_C       - set from Credit / Debit downwards
//   f_type  TXN_TYPE           - set on P2P / TOP UP / CASH OUT / ...
//   f_cp    TXN_WITH_ACC       - set on the level-10 Customer-<acc> nodes
//
// So: Pathao Pay or Customers -> everything (sampled); C3 -> that
// customer's rows; Debit -> only their debits; CASH OUT -> only their
// cash-out debits; Customer-1728... -> only the rows between the two.
//
// The LIMIT matters: with millions of rows loaded, an unbounded table
// card will hang the browser. Raise it if you want - the browser, not
// Neo4j, is what struggles first.
// A focus key that no longer exists (after a rebuild renames keys) leaves
// every filter null, which shows the unfiltered sample - the same thing
// 'root' shows. See the note in card2_expansion_graph.cypher.
WITH coalesce($neodash_focus, 'root') AS fk
OPTIONAL MATCH (f:Nav {key: fk})
WITH f.f_acc AS f_acc, f.f_dc AS f_dc, f.f_type AS f_type, f.f_cp AS f_cp
MATCH (t:Transaction)
WHERE (f_acc  IS NULL OR t.stmt_acc     = f_acc)
  AND (f_dc   IS NULL OR t.txn_type_d_c = f_dc)
  AND (f_type IS NULL OR t.txn_type     = f_type)
  AND (f_cp   IS NULL OR t.with_acc     = f_cp)
RETURN t.unq_id        AS UNQ_ID,
       t.from_date     AS FROM_DATE,
       t.to_date       AS TO_DATE,
       t.serial_no     AS SerialNo,
       t.txn_date_time AS TXN_DATE_TIME,
       t.txn_id        AS TXN_ID,
       t.txn_type      AS TXN_TYPE,
       t.account_type  AS ACCOUNT_TYPE,
       t.stmt_acc      AS STATEMENT_FOR_ACC,
       t.with_acc      AS TXN_WITH_ACC,
       t.channel       AS CHANNEL,
       t.reference     AS REFERENCE,
       t.txn_type_d_c  AS TXN_TYPE_D_C,
       t.status        AS STATUS,
       t.amount        AS TXN_AMT,
       t.balance_after AS AVAILABLE_BLC_AFTER_TXN,
       t.txn_with_info AS TXN_WITH_INFO
ORDER BY STATEMENT_FOR_ACC, TXN_DATE_TIME, SerialNo
LIMIT 2000

// CARD - "1. Pick a customer" (report type: Table)
// Click a CUSTOMER button to set $neodash_trace_acc.
// Same C1..Cn numbering as the Pathao Pay drill-down. CREDITS and
// CREDITED_TK count real statement lines only (:Canon), so the copies
// duplicated in the source are not counted.
MATCH (n:Nav:Customer)
CALL {
  WITH n
  MATCH (t:Canon)
  WHERE t.stmt_acc = n.acc AND t.txn_type_d_c = 'C'
    AND t.txn_date_time IS NOT NULL   // lets the planner use the canon_acc_dc_time index
  RETURN count(t) AS credits, sum(t.amount) AS credited
}
RETURN n.name                                AS CUSTOMER,
       n.acc                                 AS ACCOUNT,
       credits                               AS CREDITS,
       round(credited, 2)                    AS CREDITED_TK,
       CASE WHEN n.acc = $neodash_trace_acc THEN '<< selected' ELSE '' END AS SELECTED
ORDER BY n.cust_no

// CARD - "Trace rule" (report type: Table)
// Click a RULE button to set $neodash_trace_mode.
UNWIND [
  {m: 'credit_first', d: 'Debits after the credit are paid from THIS credit first'},
  {m: 'fifo',         d: 'Money already in the account is spent first, then this credit'}
] AS r
RETURN CASE WHEN r.m = coalesce($neodash_trace_mode, 'credit_first') THEN '(*) ' ELSE '( ) ' END + r.m AS RULE,
       r.d AS MEANING,
       r.m AS __mode

// CARD - "Money trail" (report type: Graph, layout tree-top-down)
//
// Same rule and parameters as trace_table.cypher - read that file's
// header for the full explanation. This card draws the result as one
// vertical chain, read top to bottom:
//
//   From <sender>                      who paid the credit in
//     | credited 500 tk
//   CREDIT 500 tk - P2P - 2024-04-07 17:59
//     | uses 200 tk - left 300 tk
//   #1 2024-04-07 19:53 - P2P 200 tk
//     | uses 250 tk - left 50 tk
//   #2 ...
//     | uses 50 tk - left 0 tk
//   #3 2024-04-08 10:30 - CASH OUT 100 tk
//     |
//   TERMINATED 2024-04-08 10:30:47     the debit that used the last paisa
//
// READABILITY. A large credit can take hundreds of debits to use up. The
// chain always shows the first 6 and the last 6 steps - the last one being
// the terminating debit - and folds everything in between into one
// "... n more debits" node carrying their total. The step table below the
// graph lists every step.
//
// Nothing here is stored: the chain is built from APOC virtual nodes on
// each run, so it never touches the database.
WITH coalesce($neodash_trace_credit, '') AS ck,
     coalesce($neodash_trace_mode, 'credit_first') AS mode
MATCH (c:Canon {row_key: ck})
WHERE c.stmt_acc = coalesce($neodash_trace_acc, '')   // switching customer clears the trail
WITH c, mode,
     toInteger(round(c.amount * 1000000)) AS credit_u,
     toInteger(round((c.balance_after - c.amount) * 1000000)) AS prior_u
WITH c, mode, credit_u,
     CASE WHEN mode = 'fifo' AND prior_u > 0 THEN prior_u ELSE 0 END AS skip_u
CALL {
  WITH c
  MATCH (d:Canon)
  WHERE d.stmt_acc = c.stmt_acc
    AND d.txn_type_d_c = 'D'
    AND d.txn_date_time >= c.txn_date_time
    AND (d.txn_date_time > c.txn_date_time OR coalesce(d.serial_no, 0) > coalesce(c.serial_no, 0))
  WITH d ORDER BY d.txn_date_time, d.serial_no
  LIMIT 20000
  RETURN collect(d) AS ds
}
WITH c, mode, credit_u, skip_u, ds, skip_u + credit_u AS target_u,
     apoc.coll.runningTotal([x IN ds | toInteger(round(x.amount * 1000000))]) AS cum
WITH c, mode, credit_u, skip_u, target_u, ds, cum,
     coalesce([i IN range(0, size(ds) - 1) WHERE cum[i] >= target_u][0], -1) AS cut
WITH c, mode, credit_u, ds, cut,
     [i IN range(0, CASE WHEN cut >= 0 THEN cut ELSE size(ds) - 1 END) |
        {d: ds[i], n: i,
         used: (CASE WHEN cum[i] < target_u THEN cum[i] ELSE target_u END)
             - (CASE WHEN i > 0 AND cum[i - 1] > skip_u THEN cum[i - 1] ELSE skip_u END),
         left: target_u - (CASE WHEN cum[i] < target_u THEN cum[i] ELSE target_u END)}
     ] AS all_steps
WITH c, mode, credit_u, ds, cut,
     [s IN all_steps WHERE s.used > 0] AS steps
WITH c, mode, credit_u, ds, cut, steps,
     reduce(u = 0, s IN steps | u + s.used) AS used_total_u
// Fold the middle of a long chain into one node.
WITH c, mode, credit_u, ds, cut, steps, used_total_u,
     CASE WHEN size(steps) <= 13
          THEN [k IN range(0, size(steps) - 1) | {kind: 'step', k: k, s: steps[k]}]
          ELSE [k IN range(0, 5) | {kind: 'step', k: k, s: steps[k]}]
             + [{kind: 'gap', k: 6, s: null,
                 cnt: size(steps) - 12,
                 amt: reduce(u = 0, s IN steps[6 .. size(steps) - 6] | u + s.used),
                 left: steps[size(steps) - 7].left}]
             + [k IN range(size(steps) - 6, size(steps) - 1) | {kind: 'step', k: k, s: steps[k]}]
     END AS shown

// --- the nodes ------------------------------------------------------
CALL apoc.create.vNode(['TraceSource'], {
  name: 'From ' + coalesce(c.with_acc, '?'),
  account: c.with_acc
}) YIELD node AS src
CALL apoc.create.vNode(['TraceCredit'], {
  name: 'CREDIT ' + apoc.number.format(c.amount, '#,##0.######') + ' tk  -  ' + c.txn_type +
        '  -  ' + substring(c.txn_date_time, 0, 16),
  customer: c.stmt_acc,
  amount: c.amount,
  txn_type: c.txn_type,
  txn_date_time: c.txn_date_time,
  txn_id: c.txn_id,
  balance_after: c.balance_after,
  mode: mode
}) YIELD node AS cr
CALL apoc.create.vRelationship(src, 'CREDITED', {
  name: 'credited ' + apoc.number.format(c.amount, '#,##0.######') + ' tk',
  amount: c.amount
}, cr) YIELD rel AS r0

CALL {
  WITH shown
  UNWIND shown AS x
  CALL apoc.create.vNode(
    [CASE x.kind WHEN 'gap' THEN 'TraceGap' ELSE 'TraceStep' END],
    CASE x.kind
      WHEN 'gap' THEN {
        name: '... ' + toString(x.cnt) + ' more debits  -  ' +
              apoc.number.format(x.amt / 1000000.0, '#,##0.######') + ' tk from this credit',
        debits: x.cnt,
        used_from_credit: x.amt / 1000000.0,
        credit_left_after: x.left / 1000000.0
      }
      ELSE {
        name: '#' + toString(x.k + 1) + '  ' + substring(x.s.d.txn_date_time, 0, 16) + '  -  ' +
              x.s.d.txn_type + '  ' + apoc.number.format(x.s.d.amount, '#,##0.######') + ' tk',
        step: x.k + 1,
        txn_date_time: x.s.d.txn_date_time,
        txn_type: x.s.d.txn_type,
        to_account: x.s.d.with_acc,
        debit_amount: x.s.d.amount,
        used_from_credit: x.s.used / 1000000.0,
        credit_left_after: x.s.left / 1000000.0,
        balance_after: x.s.d.balance_after,
        txn_id: x.s.d.txn_id
      }
    END
  ) YIELD node
  RETURN collect({node: node, x: x}) AS chain
}

// --- the end of the trail -------------------------------------------
WITH c, cr, src, r0, ds, cut, steps, chain, credit_u, used_total_u,
     CASE WHEN cut >= 0 THEN steps[size(steps) - 1].d ELSE null END AS term
CALL apoc.create.vNode(['TraceEnd'], CASE
  WHEN term IS NOT NULL THEN {
    name: 'TERMINATED  ' + term.txn_date_time + '  (step ' + toString(size(steps)) + ')',
    terminated: true,
    at: term.txn_date_time,
    by_txn_type: term.txn_type,
    to_account: term.with_acc,
    steps: size(steps)
  }
  WHEN size(ds) >= 20000 THEN {
    name: 'NOT TERMINATED within 20,000 debits  -  ' +
          apoc.number.format((credit_u - used_total_u) / 1000000.0, '#,##0.######') + ' tk left',
    terminated: false,
    left: (credit_u - used_total_u) / 1000000.0
  }
  ELSE {
    name: 'NOT TERMINATED  -  ' +
          apoc.number.format((credit_u - used_total_u) / 1000000.0, '#,##0.######') +
          ' tk still unspent at end of data',
    terminated: false,
    left: (credit_u - used_total_u) / 1000000.0
  }
END) YIELD node AS endn

// --- the edges: credit -> step 1 -> step 2 -> ... -> end -------------
WITH src, cr, r0, endn, chain,
     [cr] + [x IN chain | x.node] AS froms,
     [x IN chain | x] AS tos
CALL {
  WITH froms, tos
  UNWIND range(0, size(tos) - 1) AS i
  WITH froms[i] AS a, tos[i] AS t
  CALL apoc.create.vRelationship(a, 'SPENT', {
    name: CASE t.x.kind
            WHEN 'gap' THEN 'uses ' + apoc.number.format(t.x.amt / 1000000.0, '#,##0.######') +
                            ' tk  -  left ' + apoc.number.format(t.x.left / 1000000.0, '#,##0.######') + ' tk'
            ELSE 'uses ' + apoc.number.format(t.x.s.used / 1000000.0, '#,##0.######') +
                 ' tk  -  left ' + apoc.number.format(t.x.s.left / 1000000.0, '#,##0.######') + ' tk'
          END
  }, t.node) YIELD rel
  RETURN collect(rel) AS rels
}
WITH src, cr, r0, endn, rels, [x IN chain | x.node] AS step_nodes,
     CASE WHEN size(chain) = 0 THEN cr ELSE chain[size(chain) - 1].node END AS last
CALL apoc.create.vRelationship(last, 'ENDS', {
  name: CASE WHEN endn.terminated THEN '0 tk left' ELSE 'trail ends' END
}, endn) YIELD rel AS rEnd
// every node must be returned, not only the relationships between them -
// NeoDash cannot draw a relationship whose end node is missing
RETURN src, cr, step_nodes, endn, r0, rels, rEnd

// CARD - "Money trail - step by step" (report type: Table)
//
// Parameters (set by clicking in the other cards on the Money Trail page):
//   $neodash_trace_credit  row_key of the credit being traced
//   $neodash_trace_mode    'credit_first' (default) or 'fifo'
//
// THE RULE. Take one credit, e.g. 500 tk into a customer's account. Walk
// that customer's debits forward in date-time order - P2P, TOP UP, CASH
// OUT, PAYMENT, service fees, everything that left the account - and
// charge each one against the credit until nothing is left. The debit
// that takes the balance of the credit to zero is where the amount
// TERMINATES.
//
//   credit_first  every debit after the credit is paid out of THIS credit
//                 first. What you asked for: "after the credited amount,
//                 where did the user debit it".
//   fifo          money already in the account before the credit is spent
//                 first (first in, first out); this credit starts being
//                 used only once that older balance is gone.
//
// EXACTNESS. Amounts are converted to integer micro-taka (x 1,000,000)
// before any adding up, so there is no floating-point drift: the trail
// does not stop while even 0.0001 tk of the credit is left, and stops on
// exactly the debit that uses the last of it.
//
// Reads :Canon rows only (see cypher/05_build_trace_layer.cypher) so the
// copies duplicated in the source extract are not counted 414 times.
WITH coalesce($neodash_trace_credit, '') AS ck,
     coalesce($neodash_trace_mode, 'credit_first') AS mode,
     20000 AS max_debits   // keep in step with the LIMIT below
MATCH (c:Canon {row_key: ck})
WHERE c.stmt_acc = coalesce($neodash_trace_acc, '')   // switching customer clears the trail
WITH c, mode, max_debits,
     toInteger(round(c.amount * 1000000)) AS credit_u,
     toInteger(round((c.balance_after - c.amount) * 1000000)) AS prior_u
WITH c, mode, max_debits, credit_u,
     CASE WHEN mode = 'fifo' AND prior_u > 0 THEN prior_u ELSE 0 END AS skip_u
CALL {
  WITH c
  MATCH (d:Canon)
  WHERE d.stmt_acc = c.stmt_acc
    AND d.txn_type_d_c = 'D'
    AND d.txn_date_time >= c.txn_date_time
    AND (d.txn_date_time > c.txn_date_time OR coalesce(d.serial_no, 0) > coalesce(c.serial_no, 0))
  WITH d ORDER BY d.txn_date_time, d.serial_no
  LIMIT 20000
  RETURN collect(d) AS ds
}
WITH c, mode, credit_u, skip_u, ds, skip_u + credit_u AS target_u,
     apoc.coll.runningTotal([x IN ds | toInteger(round(x.amount * 1000000))]) AS cum
WITH c, mode, credit_u, skip_u, target_u, ds, cum,
     coalesce([i IN range(0, size(ds) - 1) WHERE cum[i] >= target_u][0], -1) AS cut
UNWIND range(0, CASE WHEN cut >= 0 THEN cut ELSE size(ds) - 1 END) AS i
WITH c, mode, credit_u, skip_u, target_u, ds, cum, cut, i,
     CASE WHEN i = 0 THEN 0 ELSE cum[i - 1] END AS before_u
WITH c, mode, credit_u, target_u, ds[i] AS d, i, cut,
     (CASE WHEN cum[i] < target_u THEN cum[i] ELSE target_u END)
       - (CASE WHEN before_u > skip_u THEN before_u ELSE skip_u END) AS used_u,
     target_u - (CASE WHEN cum[i] < target_u THEN cum[i] ELSE target_u END) AS left_u
WHERE used_u > 0
WITH c, d, i, cut, used_u, left_u
ORDER BY i
WITH c, collect({d: d, i: i, cut: cut, used: used_u, left: left_u}) AS steps
UNWIND range(0, size(steps) - 1) AS k
WITH c, steps[k] AS s, k
RETURN k + 1                                          AS STEP,
       s.d.txn_date_time                              AS TXN_DATE_TIME,
       s.d.txn_type                                   AS TXN_TYPE,
       s.d.with_acc                                   AS TXN_WITH_ACC,
       s.d.amount                                     AS DEBIT_AMT,
       s.used / 1000000.0                             AS FROM_THIS_CREDIT,
       s.left / 1000000.0                             AS CREDIT_LEFT_AFTER,
       CASE WHEN s.i = s.cut THEN 'TERMINATED HERE' ELSE '' END AS STATUS,
       s.d.balance_after                              AS AVAILABLE_BLC_AFTER_TXN,
       s.d.txn_id                                     AS TXN_ID,
       s.d.channel                                    AS CHANNEL,
       s.d.reference                                  AS REFERENCE
ORDER BY STEP
